document.querySelectorAll('header nav a[href^="#"]').forEach(link=>{link.addEventListener("click",e=>{e.preventDefault();const target=document.querySelector(link.getAttribute("href"));if(!target)return;document.documentElement.style.scrollSnapType="none";const prefersReduced=window.matchMedia("(prefers-reduced-motion: reduce)").matches;target.scrollIntoView({behavior:prefersReduced?"instant":"smooth"});setTimeout(()=>{document.documentElement.style.scrollSnapType="y mandatory"},1e3)})});